fn default_plugin_wasm() -> Option<PathBuf> {
    let exe = std::env::current_exe().ok()?;
    let repo = exe.ancestors().nth(3)?;
    let wasm = repo.join("crates/panopt-zellij/target/wasm32-wasip1/release/panopt-zellij.wasm");
