1811	            other => panic!("TOOL_SURFACE entry `{name}` produced a non-object schema: {other:?}"),
1812	        };
1813	        let attr = rmcp::model::Tool::new(name, def.description, Arc::new(schema_obj));
1814	        router.add_route(ToolRoute::new_dyn(attr, move |ctx| {
1815	            Box::pin(dispatch_local(name, ctx))
1816	        }));
1817	    }
1818	    router
